		public override void Update()
		{
			PlayAudio();
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				LightningBurst.CreateBurst(parent.attack.transform.position, parent.skillCategory, parent.attackSkillID, 2, parent.burstRadius);
