	public class SpinAttackState(string newName, FSM newFSM, OrbMetalFamiliar newEnt) : State<OrbMetalFamiliar>(newName, newFSM, newEnt)
	{
		private ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch(0.5f);

		private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(0.5f);

		private Vector3 targetVector;

		private bool atkStarted;

		private bool atkCompleted;

		public override void OnEnter()
		{
			parent.movement.EndMovement();
			parent.anim.Play("Speedup", -1, 0f);
			parent.spriteRenderer.material.SetColor("_OutlineColor", Color.cyan);
			PlayAudio();
			targetVector = (parent.closestTargetInfo.position - parent.transform.position).normalized;
			parent.movement.moveVector = targetVector;
			parent.movement.dashVector = targetVector;
			delayStopwatch.IsRunning = true;
			atkStarted = false;
			atkCompleted = false;
		}

		public override void Update()
		{
			if (!delayStopwatch.IsRunning)
			{
				if (!atkStarted)
				{
					atkStarted = true;
				}
				if (atkCompleted)
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
			}
		}

		public override void FixedUpdate()
		{
			if (atkStarted && !atkCompleted)
			{
				PlayAudio();
				if (parent.movement.DashToTarget())
				{
					atkCompleted = true;
					delayStopwatch.IsRunning = true;
					parent.movement.MoveToMoveVector(6f);
					parent.anim.Play("Idle", -1, 0f);
					parent.spriteRenderer.material.SetColor("_OutlineColor", Color.clear);
				}
			}
		}

		public override void OnExit()
		{
			parent.anim.Play("Idle", -1, 0f);
			parent.spriteRenderer.material.SetColor("_OutlineColor", Color.clear);
		}

		private void PlayAudio()
		{
			if (!audioStopwatch.IsRunning)
			{
				audioStopwatch.IsRunning = true;
				SoundManager.PlayAudioWithDistance("StandardSpin", parent.transform.position);
			}
		}
	}

	private static GameObject prefab;

	public ParticleSystem lightPartSys;

	public ParticleSystem.ShapeModule shapeMod;

	public ParticleSystem.EmissionModule emitMod;

	public SpriteRenderer bodySprite;

	public SpriteRenderer topSprite;

	public SpriteRenderer bladeSprite;

	public Collider2D atkCollider;

	private float burstDelay = 1f;

	private float burstRadius = 3f;

	private ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(0.75f);

	private ChaosQuickStopwatch destructTimer = new ChaosQuickStopwatch(0.25f);

	private ChaosQuickStopwatch flashTimer = new ChaosQuickStopwatch(0.25f);

	private bool selfDestructQueued;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Enemies/OrbMetalFamiliar.prefab"));

	public override void InitComponents()
	{
		base.InitComponents();
		attack = transform.Find("EnemyAttackBox").GetComponent<Attack>();
		shapeMod = lightPartSys.shape;
		emitMod = lightPartSys.emission;
	}

	public override void InitFSM()
	{
		attackStateName = "Attack";
		base.InitFSM();
		fsm.AddState(new BurstAttackState("Burst", fsm, this));
		fsm.AddState(new BurstAttackState("SelfDestruct", fsm, this)
		{
			isSelfDestruct = true
		});
		fsm.AddState(new SpinAttackState("Attack", fsm, this));
		fsm.AddState(new MetalSpawnState("Spawn", fsm, this));
		fsm.ReplaceState(new MetalDeadState("Dead", fsm, this));
		fsm.ChangeState("Spawn");
	}

	public override void Start()
	{
		base.Start();
		anim.Play("Spawn", -1, 0f);
		bodySprite.material.SetColor("_FlashColor", Color.yellow);
		topSprite.material.SetColor("_FlashColor", Color.yellow);
		bladeSprite.material.SetColor("_FlashColor", Color.yellow);
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (!atkStopwatch.IsRunning)
		{
			atkStopwatch.IsRunning = true;
			atkCollider.enabled = false;
			atkCollider.enabled = true;
		}
	}

	public override void Update()
	{
		base.Update();
		if (destructTimer.IsRunning)
		{
			if (!flashTimer.IsRunning)
			{
				flashTimer.SetDelay(Mathf.Clamp(0.5f * destructTimer.TimePercentage, 0.15f, 0.4f));
				flashTimer.IsRunning = true;
			}
			bodySprite.material.SetFloat("_FlashAmount", Mathf.Lerp(0f, 0.4f, flashTimer.TimePercentage + 0.15f));
			topSprite.material.SetFloat("_FlashAmount", Mathf.Lerp(0f, 0.4f, flashTimer.TimePercentage + 0.15f));
		}
	}

	public override void SetXScale()
	{
	}

	public void QueueBurst(float givenRadius = 3f, float givenDelay = 1f, bool selfDestruct = false, bool emitHitEffect = false)
	{
		if (!selfDestructQueued)
		{
			selfDestructQueued = selfDestruct;
			if (!lightPartSys.isPlaying)
			{
				lightPartSys.Play();
				Globals.ChaosInst<LightningStrike>(LightningStrike.Prefab, null, spriteRenderer.transform.position).spawnBurnMark = false;
			}
			if (emitHitEffect)
			{
				PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffectLarge").Emit(1, transform.position + Vector3.up);
			}
			if (selfDestruct && givenDelay > 0f)
			{
				destructTimer.SetDelay(givenDelay);
				destructTimer.IsRunning = true;
			}
			burstRadius = givenRadius;
			burstDelay = givenDelay;
			fsm.ChangeState((!selfDestruct) ? "Burst" : "SelfDestruct");
		}
	}
}
