using UnityEngine;

public class OrbRevolveFamiliar : OrbFamiliar
{
	public class OrbRevolveHurtState : OrbHurtState
	{
		public new OrbRevolveFamiliar parent;

		public OrbRevolveHurtState(string newName, FSM newFSM, OrbRevolveFamiliar newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.ToggleOrbits(status: false);
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.ToggleOrbits(status: true);
		}

		public override void ExitTransition()
		{
			fsm.ChangeState(fsm.defaultStateName);
		}
	}

	public class OrbRevolveDeadState : EnemyDeadState
	{
		public new OrbRevolveFamiliar parent;

		public OrbRevolveDeadState(string newName, FSM newFSM, OrbRevolveFamiliar newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			AttackOrb[] atkOrbArray = parent.atkOrbArray;
			foreach (AttackOrb attackOrb in atkOrbArray)
			{
				if (attackOrb != null)
				{
					attackOrb.DestroyAttackOrb();
				}
			}
		}
	}

	private static GameObject prefab;

	private int atkOrbSpawnCount;

	private AttackOrb[] atkOrbArray;

	private bool expanding = true;

	private bool allowOrbit = true;

	private float orbitLerpValue;

	private ChaosQuickStopwatch sfxStopwatch = new ChaosQuickStopwatch(0.5f);

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Enemies/OrbRevolveFamiliar.prefab"));

	public override void InitComponents()
	{
		base.InitComponents();
		attackSkillID = "OrbRevolveFamiliarAttack";
	}

	public override void Start()
	{
		base.Start();
		atkOrbSpawnCount = 3;
		atkOrbArray = new AttackOrb[atkOrbSpawnCount];
		SummonOrbs();
	}

	public override void InitFSM()
	{
		base.InitFSM();
		fsm.ReplaceState(new OrbRevolveHurtState("Hurt", fsm, this));
		fsm.ReplaceState(new OrbRevolveDeadState("Dead", fsm, this));
	}

	public override void Update()
	{
		base.Update();
		HandleOrbSpin();
	}

	private void SummonOrbs()
	{
		Vector2 normalized = Random.insideUnitCircle.normalized;
		for (int i = 0; i < atkOrbSpawnCount; i++)
		{
			AttackOrb attackOrb = Globals.ChaosInst<AttackOrb>(AttackOrb.Prefab, transform.parent, (Vector2)hurtBoxTransform.position + Globals.GetRotatedCircleVector(atkOrbSpawnCount, i, normalized));
			attackOrb.attack.SetAttackInfo(skillCategory, attackSkillID);
			attackOrb.orbitTrans = hurtBoxTransform;
			atkOrbArray[i] = attackOrb;
		}
		attackStopwatch.IsRunning = true;
	}

	private void HandleOrbSpin()
	{
		orbitLerpValue = attackStopwatch.TimePercentage;
		for (int i = 0; i < atkOrbSpawnCount; i++)
		{
			if (!(atkOrbArray[i] == null))
			{
				atkOrbArray[i].movement.orbitRadius = 0.5f + 2f * ((!expanding) ? (1f - orbitLerpValue) : orbitLerpValue);
			}
		}
		if (allowOrbit && orbitLerpValue == 1f)
		{
			expanding = !expanding;
			attackStopwatch.IsRunning = true;
		}
		if (!sfxStopwatch.IsRunning)
		{
			sfxStopwatch.IsRunning = true;
			string audioID = "AirWindup";
			Transform originTrans = transform;
			SoundManager.PlayAudioWithDistance(audioID, null, originTrans, 24f, 0.05f);
		}
	}

	private void ToggleOrbits(bool status)
	{
		allowOrbit = status;
		for (int i = 0; i < atkOrbSpawnCount; i++)
		{
			if (atkOrbArray[i] != null)
			{
				atkOrbArray[i].allowOrbit = allowOrbit;
			}
		}
		attackStopwatch.IsPaused = !allowOrbit;
	}
}
