		fsm.AddState(new RogueLungeState("Lunge", fsm, this, 0, 8, 0f, 6f, 0f, newAuto: false));
		fsm.AddState(new DashState("Dash", fsm, this, 1, 10, 0f, 16f, 0.35f)
		{
			allowReset = true,
			dashOverPits = true,
			onlyDashOverPits = true,
			castingAnimName = "Dash"
		});
		fsm.ChangeState(fsm.defaultStateName);
