		maxPitch = 1.1f;
	}

	public override void Update()
	{
		base.Update();
		HandleStealthCooldown();
	}

	public void HandleStealthCooldown()
	{
		if (IsStealthed && !queueStealthCooldown)
		{
			queueStealthCooldown = true;
		}
		if (!IsStealthed && queueStealthCooldown)
		{
			queueStealthCooldown = false;
			if (stealthState != null)
			{
				stealthState.StartCooldown(stealthCDTime);
			}
		}
		queueStealthCooldown = IsStealthed;
	}
