	public float explosionTime;

	public float explosionPauseTime;

	private float timeUntilFlash;

	private int explosionStopwatchID;

	private int pauseStopwatchID;

	private int flashStopwatchID;

	public float speedRamp;

	private NumVarStatMod spiderSpeedUpMod;

	internal Light spiderLight;

	private CastingCircle castingCircle;

	private GameObject iceBombPrefab;

	private float explosionScale;

	internal bool timerStarted;

	public override void Awake()
	{
		base.Awake();
		InitFSM();
		InitAudio();
		explosionTime = 3.5f;
		explosionScale = 1.5f;
		iceBombPrefab = ChaosBundle.Get("Assets/Prefabs/Items/IceBomb.prefab");
		spiderSpeedUpMod = new NumVarStatMod("SpiderSpeedUpMod", movement.moveSpeedStat.CurrentValue, 10, VarStatModType.OverrideWithMods);
	}

	private new void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new IdleState("Idle", fsm, this)
		{
			multiAnimIdle = true
		});
		fsm.AddState(new AttackState("Attack", fsm, this));
		fsm.AddState(new ChaseState("Chase", fsm, this));
		fsm.AddState(new PauseState("Pause", fsm, this));
		fsm.AddState(new EnemyDeadState("Dead", fsm, this));
		fsm.AddState(new EnemyHurtState("Hurt", fsm, this));
		fsm.AddState(new EnemyFallState("Fall", fsm, this));
		fsm.AddState(new EnemyFrozenState("Frozen", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}

	public override void InitComponents()
	{
		base.InitComponents();
		spiderLight = transform.Find("SpiderLight").GetComponent<Light>();
	}

	private new void InitAudio()
	{
		hurtAudioIDs = new string[1] { "SpiderHurt" };
		minPitch = 0.9f;
		maxPitch = 1.3f;
	}

	public IEnumerator ExplosionTimer()
	{
		timeUntilFlash = explosionTime * 0.08f;
		explosionStopwatchID = ChaosStopwatch.Begin(explosionTime);
		flashStopwatchID = ChaosStopwatch.Begin(timeUntilFlash);
		spiderLight.intensity = 1.6f;
		bool redPhase = true;
		float currentSpeed = movement.moveSpeedStat.CurrentValue;
		castingCircle = CastingCirclePool.Spawn("DrawInsideOut", transform.position, parentObj: gameObject, color: CastingCircle.enemyColor, drawTime: explosionPauseTime + explosionTime, disableWithParentVal: true, trackParentVal: true, useCastTimeVal: false, castTimeVal: 0f, unitSizeX: transform.localScale.x * ((CircleCollider2D)attack.collider).radius);
		while (!ChaosStopwatch.Check(explosionStopwatchID) && !fsm.currentStateName.Contains("Dead") && !fsm.currentStateName.Contains("Fall"))
		{
			currentSpeed += speedRamp * Time.deltaTime;
			spiderSpeedUpMod.modValue = currentSpeed;
			movement.moveSpeedStat.AddMod(spiderSpeedUpMod);
			if (ChaosStopwatch.Check(flashStopwatchID))
			{
				explosionTime -= timeUntilFlash;
				timeUntilFlash = explosionTime * 0.08f;
				flashStopwatchID = ChaosStopwatch.Begin(timeUntilFlash);
				spiderLight.intensity = ((!redPhase) ? 1.6f : 0f);
				redPhase = !redPhase;
			}
			yield return null;
		}
		movement.moveSpeedStat.RemoveMod(spiderSpeedUpMod.ID);
		movement.EndMovement();
		spiderLight.intensity = 3f;
		if (!fsm.currentStateName.Contains("Dead"))
		{
			fsm.ChangeState("Pause");
		}
		pauseStopwatchID = ChaosStopwatch.Begin(explosionPauseTime);
		while (!ChaosStopwatch.Check(pauseStopwatchID) && !fsm.currentStateName.Contains("Dead") && !fsm.currentStateName.Contains("Fall"))
		{
			yield return null;
		}
		if (fsm.currentStateName.Contains("Dead") || fsm.currentStateName.Contains("Fall"))
		{
			redPhase = false;
			spiderLight.intensity = 0f;
			yield break;
		}
		fsm.QueueChangeState("Attack");
		GameObject newExplosion = Object.Instantiate(iceBombPrefab, transform.position, Quaternion.Euler(0f, 0f, 0f));
		IceBomb newIceBomb = newExplosion.GetComponent<IceBomb>();
		newIceBomb.fuseDuration = 0f;
		newIceBomb.startHidden = true;
		newIceBomb.attackBox.SetAttackInfo(skillCategory, "FrostSpiderExplosion");
		newIceBomb.attackAllies = true;
		newExplosion.transform.SetParent(transform);
		redPhase = false;
		spiderLight.intensity = 0f;
		castingCircle.Reset();
		CameraController.ShakeCamera(2f);
	}
}
