		private Vector2 dashVector;

		private float dashRange = 7f;

		private bool dashStarted;

		private bool dashCompleted;

		public NumVarStatMod dashSpeedMod;

		public NumVarStatMod dashDurationMod;

		private Vector3 armVector;

		private int maxStrafeCount;

		private int strafeCounter;

		public new SuperArcher parent;

		public SuperArcherStrafeState(string newName, FSM newFSM, SuperArcher newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
		{
			parent = newEnt;
			requireLineOfSight = false;
			castingAnimName = "Dash";
			usePowerUpEffect = false;
			projectilePrefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/BaseArrow.prefab");
			dashSpeedMod = new NumVarStatMod(name, 22f, 10, VarStatModType.OverrideWithMods);
			dashDurationMod = new NumVarStatMod(name, 0.25f, 10, VarStatModType.OverrideWithMods);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
			string audioID = "StandardSlam";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			if (strafeCounter == 0)
			{
				strafeCounter = 1;
				maxStrafeCount = (int)Mathf.Lerp(1f, 3f, currentDiffValue);
				windupTime = StdWindupTime * 1.25f;
			}
			else
			{
				windupTime = StdWindupTime * 0.85f;
			}
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			exitTime = StdExitTime * 1.25f;
			dashVector = ((parent.closestTargetInfo != null) ? GetStrafeVector(parent.closestTargetInfo.transform.position) : Vector2.zero);
			dashStarted = false;
			dashCompleted = false;
			shotCounter = 0;
			shotCompleted = false;
			SetTargetLines();
			targetLinesActive = true;
			parent.movement.dashSpeedStat.AddMod(dashSpeedMod);
			parent.movement.dashDurationStat.AddMod(dashDurationMod);
			parent.ToggleFloorContact(allyCollisionOn: false);
			parent.TogglePreventFallCollider(status: false);
			parent.FaceTarget((Vector2)parent.transform.position + dashVector * ((!useStrafe) ? (-1f) : 1f), 2);
			parent.anim.Play("Slide", -1, 1f);
		}

		public override void ExecuteSkill()
		{
			if (targetLinesActive)
			{
				targetLinesActive = false;
				if (!useStrafe)
				{
					parent.FaceTarget((Vector2)parent.transform.position + shootVector, 2);
					if (parent.isFacingRight)
					{
						parent.anim.Play("JumpAttackFront", -1, 0f);
					}
					else
					{
						parent.anim.Play("JumpAttackBack", -1, 0f);
					}
					armVector = Globals.GetRotationVector(shootVector);
					if (!parent.isFacingRight)
					{
						armVector.z *= -1f;
					}
					armVector.z += 90f;
					parent.bowArm.localEulerAngles = armVector;
				}
				else
				{
					parent.anim.Play("JumpAttackFront", -1, 0f);
					parent.FaceTarget((Vector2)parent.transform.position + shootVector, 2);
					armVector = Globals.GetRotationVector(Globals.GetPerpendicular(dashVector, !strafeRight));
					if (!parent.isFacingRight)
					{
						armVector.z *= -1f;
					}
					armVector.z += 90f;
					parent.bowArm.localEulerAngles = armVector;
				}
				string audioID = "StandardDash";
				Vector2? soundOrigin = parent.transform.position;
				float standardPitchRange = SoundManager.StandardPitchRange;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
				parent.movement.dashVector = dashVector;
				dashStarted = true;
				parent.SetTargetLineVisibility(givenStatus: false, Color.clear);
				DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
				int particleCount = 30;
				standardPitchRange = Globals.GetRotationVector(-dashVector).z;
				Vector3? emitPosition = parent.transform.position;
				poolItem.EmitDirBurst(particleCount, standardPitchRange, -1f, -1f, -1f, emitPosition);
				shotStopwatchID = ChaosStopwatch.Begin(shotDelay, useInterval: true, shotDelay, 5);
			}
			switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
			{
			case StopwatchState.Ready:
				ShootArrow(shootPositions[shotCounter], shootVector);
				parent.targetLines[shotCounter].IsVisible(status: false);
				shotCounter++;
				break;
			case StopwatchState.Done:
				shotCompleted = true;
				break;
			}
			if (shotCompleted && dashCompleted)
			{
				parent.anim.Play("GroundSlam", -1, 1f);
				if (strafeCounter < maxStrafeCount)
				{
					strafeCounter++;
					fsm.ChangeState(name, allowSelfTransition: true);
				}
				else
				{
					base.ExecuteSkill();
					parent.AllowHurtState(status: true);
					strafeCounter = 0;
				}
			}
		}

		public override void FixedUpdate()
		{
			if (dashStarted && !dashCompleted)
			{
				dashCompleted = parent.movement.DashToTarget();
				if (dashCompleted)
				{
					parent.movement.moveVector = dashVector;
					parent.movement.MoveToMoveVector();
				}
			}
		}

		public override void ExitTransition()
		{
			base.ExitTransition();
			parent.AllowHurtState(status: false);
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.SetTargetLineVisibility(givenStatus: false, Color.red);
			parent.movement.dashSpeedStat.RemoveMod(dashSpeedMod.ID);
			parent.movement.dashDurationStat.RemoveMod(dashDurationMod.ID);
			parent.ToggleFloorContact();
			parent.TogglePreventFallCollider(status: true);
		}

		private Vector2 GetStrafeVector(Vector2 givenTargetLoc)
		{
			useStrafe = true;
			strafeRight = Globals.RandBool;
			currentPosition = parent.transform.position;
			calcDist = Vector2.Distance(currentPosition, givenTargetLoc);
			if (calcDist > 2.5f)
			{
				calcVector = givenTargetLoc - currentPosition;
				perpendVec = Globals.GetPerpendicular(calcVector.normalized, strafeRight);
				calcPosition = givenTargetLoc + perpendVec * calcVector.magnitude;
				calcVector = (calcPosition - currentPosition).normalized;
				calcPosition = currentPosition + calcVector * dashRange;
				if (Globals.CheckLine(currentPosition, calcPosition, ChaosCollisions.layerAllWallAndObst))
				{
					return calcVector;
				}
				strafeRight = !strafeRight;
				calcPosition = givenTargetLoc - perpendVec * calcVector.magnitude;
				calcVector = (calcPosition - currentPosition).normalized;
				calcPosition = currentPosition + calcVector * dashRange;
				if (Globals.CheckLine(currentPosition, calcPosition, ChaosCollisions.layerAllWallAndObst))
				{
					return calcVector;
				}
			}
			useStrafe = false;
			calcVector = (currentPosition - givenTargetLoc).normalized;
			if (Globals.CheckCircle(currentPosition + calcVector * 3f, 0.25f, ChaosCollisions.layerAllWallAndObst))
			{
				return calcVector;
			}
			return -calcVector;
		}

		private void SetTargetLines()
		{
			shootVector = ((!useStrafe) ? (-dashVector) : Globals.GetPerpendicular(dashVector, !strafeRight));
			dashStartPosition = (Vector2)parent.transform.position + dashVector * 2f;
			for (int i = 0; i < 5; i++)
			{
				ref Vector2 reference = ref shootPositions[i];
				reference = dashStartPosition + dashVector * i + Vector2.up;
				if (parent.targetLines[i] == null)
				{
					continue;
				}
				if (!useStrafe)
				{
					if (i % 2 == 0)
					{
						parent.targetLines[i].transform.position = parent.transform.position + Vector3.up + (Vector3)shootVector * 0.5f;
						parent.targetLines[i].aimVector = shootVector;
						parent.targetLines[i].maxRange = parent.maxTargetLineLength;
					}
					else
					{
						parent.targetLines[i].transform.position = parent.transform.position + Vector3.up - (Vector3)shootVector * 0.5f;
						parent.targetLines[i].aimVector = -shootVector;
						parent.targetLines[i].maxRange = 5f;
					}
				}
				else
				{
					parent.targetLines[i].transform.position = shootPositions[i];
					parent.targetLines[i].aimVector = shootVector;
					parent.targetLines[i].maxRange = parent.maxTargetLineLength;
				}
			}
			parent.SetTargetLineVisibility(givenStatus: true, Color.red);
		}

		private void ShootArrow(Vector2 givenPosition, Vector2 givenVector)
		{
			currentProjectile = ChaosInst<Projectile>(projectilePrefab, givenPosition, Globals.GetRotationQuaternion(givenVector));
			currentProjectile.parentObject = parent.gameObject;
			currentProjectile.parentEntity = parent;
			currentProjectile.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			currentProjectile.Show();
			currentProjectile.moveVector = givenVector;
			currentProjectile.moveSpeed *= 2f;
			currentProjectile.attackBox.knockbackOverwriteVector = ((!useStrafe) ? givenVector : dashVector);
			string audioID = "WhipSwing";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
	}

public class SuperArcherSpreadShotState : SkillState
{
	public GameObject projectilePrefab;

	private Projectile currProj;

	private Projectile[] projArr = new Projectile[5];

	private Vector2 currentPosition;

	private Vector2 currentVector;

	public bool projectileCreated;

	public bool projectileReleased;

	public Vector3 aimVector;

	public Vector3 armVector;

	public float attackRangeModifier = 2f;

	public int chargeStopwatchID;

	public float chargeTimePercentage;

	public float chargeTime;

	public float chargeDelay;

	public int chargeDelayStopwatchID;

	public float attackDelay;

	public int attackDelayStopwatchID;

	public Color lineColor;

	public Color lineColorRed;

	public Color lineColorFlash;

	public float lineWidth;

	public float targetLineMaxOpacity = 0.6f;

	public bool drawSoundPlayed;

	public string shootAudioID = string.Empty;

	public bool shootAnimComplete;

	public float flashThreshold = 0.8f;

	public float flashTime = 0.02f;

	private bool flashRed = true;

	private ChaosQuickStopwatch flashTimer;

	private AudioSource windupAudio;

	private TargetInfo lockedTargetInfo;

	private bool lineLocked;

	public new SuperArcher parent;

	public SuperArcherSpreadShotState(string newName, FSM newFSM, SuperArcher newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD)
		: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
	{
		parent = newEnt;
		lineColorRed = new Color(0.8f, 0f, 0f, 0f);
		lineColorFlash = new Color(1f, 1f, 1f, 0.75f);
		lineColor = lineColorRed;
		usePowerUpEffect = false;
		projectilePrefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/BaseArrow.prefab");
		shootAudioID = "WindArrowEnd";
	}

	private Vector3 AimTowardsTarget(bool updateAimVector = true, bool updateTargetLine = true)
	{
		if (updateAimVector && parent.closestTargetInfo != null && parent.closestTargetInfo.transform != null && parent.closestTargetInfo.hurtBoxTransform != null)
		{
			parent.FaceTarget(parent.closestTargetInfo.transform.position, parent.animFacingDirections);
			aimVector = (parent.closestTargetInfo.hurtBoxTransform.position - parent.bowArm.transform.position).normalized;
			armVector = Globals.GetRotationVector(aimVector);
			if (!parent.isFacingRight)
			{
				armVector.z *= -1f;
			}
			armVector.z += 90f;
			parent.bowArm.localEulerAngles = armVector;
		}
		if (updateTargetLine)
		{
			chargeTimePercentage = ChaosStopwatch.GetTimePercentage(chargeStopwatchID);
			parent.SetTargetLineVector(aimVector);
			if (chargeTimePercentage >= flashThreshold)
			{
				if (flashTimer == null)
				{
					flashTimer = new ChaosQuickStopwatch(flashTime);
					flashTimer.IsRunning = true;
					lineColor.a = 1f;
				}
				else if (!flashTimer.IsRunning)
				{
					if (flashRed)
					{
						lineColor = lineColorRed;
						lineColor.a = 1f;
						flashRed = false;
					}
					else
					{
						flashRed = true;
						lineColor = lineColorFlash;
					}
					flashTimer.IsRunning = true;
				}
			}
			else
			{
				lineColor.a = targetLineMaxOpacity * chargeTimePercentage;
			}
			parent.SetTargetLineVisibility(givenStatus: true, lineColor);
		}
		HoldProjectiles();
		return aimVector;
	}

	private void CreateProjectiles()
	{
		currentPosition = parent.arrowSpawn.position;
		for (int i = 0; i < 5; i++)
		{
			currentVector = Globals.GetRotatedCircleVector(24, i - 2, aimVector);
			currProj = ChaosInst<Projectile>(projectilePrefab, currentPosition + currentVector, Globals.GetRotationQuaternion(currentVector));
			currProj.parentObject = parent.gameObject;
			currProj.parentEntity = parent;
			currProj.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			currProj.Show();
			currProj.attackBox.gameObject.SetActive(value: false);
			currProj.wallCollider.gameObject.SetActive(value: false);
			projArr[i] = currProj;
		}
	}

	private void HoldProjectiles()
	{
		currentPosition = parent.arrowSpawn.position;
		for (int i = 0; i < 5; i++)
		{
			if (!(projArr[i] == null))
			{
				currentVector = Globals.GetRotatedCircleVector(24, i - 2, aimVector);
				currProj = projArr[i];
				currProj.transform.position = currentPosition + currentVector;
				currProj.RefreshFlightTime();
				currProj.transform.localEulerAngles = Globals.GetRotationVector(currentVector);
			}
		}
	}

	private void ReleaseProjectiles()
	{
		for (int i = 0; i < 5; i++)
		{
			if (!(projArr[i] == null))
			{
				currentVector = Globals.GetRotatedCircleVector(24, i - 2, aimVector);
				currProj = projArr[i];
				currProj.moveVector = currentVector;
				currProj.moveSpeed *= 2f;
				currProj.attackBox.knockbackOverwriteVector = currentVector;
				currProj.attackBox.gameObject.SetActive(value: true);
				currProj.wallCollider.gameObject.SetActive(value: true);
				currProj.disableOnHit = false;
				PoolManager.GetPoolItem<DashAirBurst>().Burst((Vector2)currProj.transform.position + currentVector * 0.25f, currentVector);
			}
		}
		SoundManager.PlayAudioWithDistance("ArcherAttackRelease", parent.transform.position);
		if (shootAudioID != string.Empty)
		{
			SoundManager.PlayAudioWithDistance(shootAudioID, parent.transform.position);
		}
		projectileReleased = true;
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 30;
		float z = Globals.GetRotationVector(-aimVector).z;
		Vector3? emitPosition = parent.transform.position + Vector3.up * 0.25f;
		poolItem.EmitDirBurst(particleCount, z, -1f, -1f, -1f, emitPosition);
	}

	private void ResetProjectiles()
	{
		for (int i = 0; i < 5; i++)
		{
			if (projArr[i] != null)
			{
				projArr[i].ResetProjectile();
			}
		}
	}

	private void HandleAttackExit()
	{
		if (!shootAnimComplete)
		{
			if (parent.anim.AnimPlayed())
			{
				shootAnimComplete = true;
				parent.anim.Play("Idle");
				parent.AllowHurtState(status: true);
			}
		}
		else if (ChaosStopwatch.Check(attackDelayStopwatchID))
		{
			ExitTransition();
		}
	}

	public override void OnEnter()
	{
		base.OnEnter();
		flashRed = true;
		windupTime = StdWindupTime;
		chargeTime = windupTime * 1.25f;
		chargeDelay = windupTime;
		attackDelay = StdExitTime * 1.5f;
		chargeStopwatchID = ChaosStopwatch.Begin(chargeTime);
		chargeDelayStopwatchID = ChaosStopwatch.Begin(chargeTime + chargeDelay);
		attackDelayStopwatchID = ChaosStopwatch.Begin(chargeTime + chargeDelay + attackDelay);
		AimTowardsTarget();
		parent.anim.Play("AttackWindup");
		SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
		lineColor = lineColorRed;
		lineColor.a = 0f;
		projectileCreated = false;
		projectileReleased = false;
		shootAnimComplete = false;
		drawSoundPlayed = false;
		lineLocked = false;
	}

	public override void Update()
	{
		if (!projectileCreated)
		{
			projectileCreated = true;
			CreateProjectiles();
		}
		if (!projectileReleased)
		{
			if (parent.closestTargetInfo == null || parent.closestTargetInfo.transform == null || parent.closestTargetInfo.hurtBoxTransform == null)
			{
				parent.UpdateTargetInfo(parent.attackRadius * attackRangeModifier);
			}
			if (parent.closestTargetInfo == null)
			{
				ExitTransition();
				return;
			}
			parent.SetTargetLinePosition(parent.arrowSpawn.position);
			if (!ChaosStopwatch.Check(chargeStopwatchID))
			{
				AimTowardsTarget();
				if (!drawSoundPlayed && ChaosStopwatch.GetTimePercentage(chargeStopwatchID) > 0.25f)
				{
					drawSoundPlayed = true;
					windupAudio = SoundManager.PlayAudioWithDistance("ArcherAttackWindup", parent.transform.position);
				}
			}
			else if (!ChaosStopwatch.Check(chargeDelayStopwatchID))
			{
				if (!lineLocked)
				{
					lineLocked = true;
					lineColor = lineColorRed;
					lineColor.a = 1f;
					parent.SetTargetLineVisibility(givenStatus: true, lineColor);
				}
				HoldProjectiles();
			}
			else
			{
				parent.SetTargetLineVisibility(givenStatus: false, Color.clear);
				ReleaseProjectiles();
				parent.anim.Play("AttackRelease", -1, 0f);
			}
		}
		else
		{
			HandleAttackExit();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		if (!projectileReleased)
		{
			ResetProjectiles();
		}
		parent.SetTargetLineVisibility(givenStatus: false, Color.clear);
		if (windupAudio != null)
		{
			windupAudio.Stop();
			windupAudio = null;
		}
	}

	public override void ExitTransition()
	{
		if (parent.anim.AnimPlayed(2.5f))
		{
			parent.AllowHurtState(status: false);
			base.ExitTransition();
		}
	}
}

