			currentProjectile.attackBox.gameObject.SetActive(value: true);
			currentProjectile.wallCollider.gameObject.SetActive(value: true);
			SoundManager.PlayAudioWithDistance("ArcherAttackRelease", parent.transform.position);
			string audioID = "StandardHeavySwing";
			Vector2? soundOrigin = parent.transform.position;
			float overridePitch = Random.Range(1.1f, 1.2f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
			currentProjectile.RefreshFlightTime();
			currentProjectile.goThroughWalls = false;
			projectileReleased = true;
			PoolManager.GetPoolItem<DashAirBurst>().Burst(currentProjectile.transform.position + aimVector * 0.25f, aimVector, useOffset: false);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 30;
			overridePitch = Globals.GetRotationVector(-aimVector).z;
			Vector3? emitPosition = parent.transform.position + Vector3.up * 0.25f;
			poolItem.EmitDirBurst(particleCount, overridePitch, -1f, -1f, -1f, emitPosition);
		}
	}

	public virtual void HandleAttackExit()
	{
		if (!shootAnimComplete)
		{
			if (parent.anim.AnimPlayed())
			{
				shootAnimComplete = true;
				parent.anim.Play("Idle");
				parent.AllowHurtState(status: true);
			}
		}
		else if (ChaosStopwatch.Check(attackDelayStopwatchID))
		{
			ExitTransition();
		}
	}

	public override void OnEnter()
	{
		base.OnEnter();
		parent.enemySkillUseInProgress = false;
		currentProjectile = null;
		parent.mainTargetLine.maxRange = targetLineRange;
		parent.mainTargetLine.line.SetWidth(0.125f, 0.125f);
		flashRed = true;
		windupTime = StdWindupTime;
		chargeTime = windupTime;
		chargeDelay = windupTime;
		attackDelay = StdExitTime * 1.375f;
		chargeStopwatchID = ChaosStopwatch.Begin(chargeTime);
		chargeDelayStopwatchID = ChaosStopwatch.Begin(chargeTime + chargeDelay);
		attackDelayStopwatchID = ChaosStopwatch.Begin(chargeTime + chargeDelay + attackDelay);
		AimTowardsTarget();
		parent.anim.Play("AttackWindup");
		lineColor = lineColorRed;
		lineColor.a = 0f;
		projectileCreated = false;
		projectileReleased = false;
		shootAnimComplete = false;
		drawSoundPlayed = false;
		lineLocked = false;
	}

	public override void Update()
	{
		if (!projectileCreated)
		{
			projectileCreated = true;
			CreateProjectile();
		}
		if (!projectileReleased)
		{
			if (parent.closestTargetInfo == null || parent.closestTargetInfo.transform == null || parent.closestTargetInfo.hurtBoxTransform == null)
			{
				parent.UpdateTargetInfo(parent.attackRadius * attackRangeModifier);
			}
			if (parent.closestTargetInfo == null)
			{
				ExitTransition();
				return;
			}
			if (currentProjectile != null)
			{
				parent.mainTargetLine.transform.position = currentProjectile.transform.position;
			}
			if (!ChaosStopwatch.Check(chargeStopwatchID))
			{
				if (!parent.HandleExtraSkills(hasLOS: true, updateTarget: false, updateLOS: true))
				{
					AimTowardsTarget();
					if (!drawSoundPlayed && ChaosStopwatch.GetTimePercentage(chargeStopwatchID) > 0.25f)
					{
						drawSoundPlayed = true;
						windupAudio = SoundManager.PlayAudioWithDistance("ArcherAttackWindup", parent.transform.position);
					}
				}
			}
			else if (!ChaosStopwatch.Check(chargeDelayStopwatchID))
			{
				if (!lineLocked)
				{
					lineLocked = true;
					lineColor = lineColorRed;
					lineColor.a = 1f;
					parent.mainTargetLine.line.SetColors(lineColor, lineColor);
					parent.mainTargetLine.IsVisible(status: true);
				}
				HoldProjectile();
			}
			else
			{
				parent.mainTargetLine.IsVisible(status: false);
				ReleaseProjectile();
				parent.anim.Play("AttackRelease", -1, 0f);
			}
		}
		else
		{
			HandleAttackExit();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		if (!projectileReleased && currentProjectile != null && currentProjectile.gameObject != null)
		{
			Object.Destroy(currentProjectile.gameObject);
		}
		parent.mainTargetLine.IsVisible(status: false);
		if (windupAudio != null)
		{
			windupAudio.Stop();
		}
		windupAudio = null;
	}

	public override void ExitTransition()
	{
		if (parent.anim.AnimPlayed())
		{
			parent.AllowHurtState(status: false);
			base.ExitTransition();
		}
	}
}

