using System;
using Chaos.AnimatorExtensions;
using UnityEngine;

public class SuperBlob : Blob
{
	public class SuperBlobAttackState : BlobAttackState
	{
		private bool landed;

		private int originalFloorContactLayer;

		private float attackEnableDelay = 0.125f;

		private int attackEnableStopwatchID;

		private int maxAttackComboCount = 3;

		private int attackComboCount;

		public new SuperBlob parent;

		public SuperBlobAttackState(string newName, FSM newFSM, SuperBlob newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			randomAttackDelay = false;
			AttackDelay = 2.5f;
			collisionWaitTime = 2f;
			Attack attack = parent.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}

		public override void OnEnter()
		{
			base.OnEnter();
			landed = false;
			jumpInitiated = false;
			originalFloorContactLayer = parent.floorContact.layer;
			if (attackComboCount > 0)
			{
				parent.anim.Play("Attack", -1, 0.3f);
			}
		}

		public override void Update()
		{
			if (firstFrame)
			{
				firstFrame = false;
				return;
			}
			PlayAttackAudio();
			if (!landed)
			{
				curAnimTime = parent.anim.GetAnimTime();
				isJumping = curAnimTime > beginJumpAnimTime && curAnimTime < endJumpAnimTime;
				if (isJumping)
				{
					parent.movement.DashToTarget();
					if (!jumpInitiated)
					{
						jumpInitiated = true;
						parent.animSpeedHandler.Modify(parent.animSpeedMod, givenStatus: false);
						parent.floorContact.layer = LayerMask.NameToLayer("IgnoreEnemyAllyFloorContact");
					}
				}
				else if (jumpInitiated)
				{
					landed = true;
					parent.animSpeedHandler.Modify(parent.animSpeedMod, givenStatus: true);
					parent.movement.EndMovement();
					DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
					int particleCount = 200;
					Vector3? emitPosition = parent.transform.position;
					poolItem.EmitCircle(particleCount, 1f, -1f, -1f, emitPosition);
					CameraController.ShakeCamera();
					SoundManager.PlayAudioWithDistance("Rumble", parent.transform.position);
					parent.attack.gameObject.SetActive(value: true);
					attackEnableStopwatchID = ChaosStopwatch.Begin(attackEnableDelay);
				}
				return;
			}
			attackComboCount++;
			if (attackComboCount < maxAttackComboCount)
			{
				parent.UpdateTargetInfo();
				fsm.ChangeState(name, allowSelfTransition: true);
			}
			else if (!idleAnimPlayed)
			{
				if (ChaosStopwatch.Check(attackEnableStopwatchID))
				{
					idleAnimPlayed = true;
					parent.anim.Play("IdleDown", -1, 0f);
					parent.attack.gameObject.SetActive(value: false);
					parent.floorContact.layer = originalFloorContactLayer;
					attackDelayStopwatchID = ChaosStopwatch.Begin(AttackDelay);
				}
			}
			else if (ChaosStopwatch.Check(attackDelayStopwatchID) && ChaosStopwatch.Check(collisionStopwatchID))
			{
				attackComboCount = 0;
				parent.HandleExitTransitions();
			}
		}

		private void OnTargetHit(Entity hitEntity)
		{
			attackComboCount = maxAttackComboCount;
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.floorContact.layer = originalFloorContactLayer;
		}
	}

	public class SuperBlobDeadState : BlobDeadState
	{
		private bool blobsDead;

		private Vector2 lastBlobLocation;

		private float deathDelay = 1f;

		private int deathStopwatchID;

		private bool childBlobsSpawned;

		public new SuperBlob parent;

		public SuperBlobDeadState(string newName, FSM newFSM, SuperBlob newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			blobSpawnCount = 15;
			divideMini = false;
		}

		public override void OnEnter()
		{
			deathStopwatchID = ChaosStopwatch.Begin(deathDelay);
			lastBlobLocation = parent.transform.position;
			parent.floorContact.SetActive(value: false);
			parent.animSpeedHandler.Modify(parent.animSpeedMod, givenStatus: false);
			parent.dropLoot = false;
			parent.childrenDropLoot = false;
			parent.divide = false;
			base.OnEnter();
			for (int i = 0; i < blobSpawnCount; i++)
			{
				Vector2 value = UnityEngine.Random.Range(2f, 5f) * Globals.GetCirclePositionVector(blobSpawnCount, i);
				Blob blob = SpawnBlob(parent.transform.position, spawnAsThrown: true, value);
				blob.transform.SetParent(parent.childBlobContainer);
				blob.divide = true;
				blob.parentSummoner = parent.gameObject;
				blob.summoned = true;
			}
		}

		public override void Update()
		{
			if (!blobsDead)
			{
				if (ChaosStopwatch.Check(deathStopwatchID))
				{
					blobsDead = parent.childBlobContainer.childCount == 0;
					if (!blobsDead)
					{
						lastBlobLocation = parent.childBlobContainer.GetChild(0).position;
					}
					else if (parent.childBlobContainer != null)
					{
						UnityEngine.Object.Destroy(parent.childBlobContainer.gameObject);
						GameController.stageTitleUI.AnnounceVictory();
						SoundManager.PlayAudio("StageVictory");
					}
				}
			}
			else
			{
				base.Update();
			}
		}
	}

	private Transform childBlobContainer;

	private HealthBar healthBar;

	private NumVarStatMod animSpeedMod;

	public override void Awake()
	{
		base.Awake();
		animSpeedMod = new NumVarStatMod("SuperBlob", -0.25f, 10, VarStatModType.Multiplicative);
	}

	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new SuperBlobAttackState("Attack", fsm, this));
		fsm.AddState(new SuperBlobDeadState("Dead", fsm, this));
		fsm.AddState(new BlobIdleState("Idle", fsm, this));
		fsm.AddState(new EnemyFallState("Fall", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}

	public override void InitAudio()
	{
		base.InitAudio();
		minPitch = 0.5f;
		maxPitch = 0.6f;
	}

	public override void Start()
	{
		base.Start();
		animSpeedHandler.Modify(animSpeedMod, givenStatus: true);
		childBlobContainer = new GameObject("SuperBlobChildren").transform;
		childBlobContainer.transform.SetParent(transform.parent);
		chestLootTableID = "TreasureChestMiniBoss";
		attackSkillID = "SuperBlobAttack";
		if (Application.loadedLevelName == "Tutorial")
		{
			health.healthStat.AddMod(new NumVarStatMod("Tutorial", 125f, 10, VarStatModType.Override, fillToNewMax: true));
		}
		healthBar = Globals.ChaosInst<HealthBar>(HealthBar.Prefab);
		healthBar.parentTrans = transform;
		healthBar.parentHealth = health;
		healthBar.SetBarDimensions(0.4f, 0.46f, 0.2f, 0.02f);
		if (spriteRenderer.material.HasProperty("_PaletteCount"))
		{
			int num = (int)spriteRenderer.material.GetFloat("_PaletteCount");
			if (num > EnemyElementCount + 1)
			{
				spriteRenderer.material.SetFloat("_PaletteIndex", MiniBoss.miniBossPaletteIndex);
				paletteIndex = MiniBoss.miniBossPaletteIndex;
			}
		}
	}
}

