	public class SuperCoffinBlockBounceState : SkillState
	{
		private float delayTime = 0.5f;

		private int delayStopwatchID;

		private bool atkCompleted;

		private int maxBounceCount = 10;

		private Vector2 perpendVec;

		private float throwTime;

		public new SuperCoffin parent;

		public SuperCoffinBlockBounceState(string newName, FSM newFSM, SuperCoffin newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
		{
			parent = newEnt;
			usePowerUpEffect = false;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.anim.Play("ScoopRight", -1, 0f);
			SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
			windupTime = StdWindupTime;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			exitTime = StdExitTime * 2f;
			throwTime = Mathf.Lerp(0.5f, 0.4f, currentDiffValue);
			atkCompleted = false;
		}

		public override void ExecuteSkill()
		{
			if (!atkCompleted)
			{
				atkCompleted = true;
				delayStopwatchID = ChaosStopwatch.Begin(delayTime);
				if (parent.UpdateTargetInfo() != null)
				{
					ThrowBouncingBlocks(parent.transform.position, (parent.closestTargetInfo.position - parent.transform.position).normalized);
					parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
				}
				parent.anim.Play("ScoopRight", -1, 0.5f);
			}
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				parent.AllowHurtState(status: true);
				base.ExecuteSkill();
			}
		}

		public override void ExitTransition()
		{
			fsm.ChangeState("Ready");
		}

		private void ThrowBouncingBlocks(Vector2 givenPosition, Vector2 givenVector)
		{
			perpendVec = Globals.GetPerpendicular(givenVector) * 1.5f;
			CreateBouncingBlock(givenPosition, givenVector, throwTime);
			CreateBouncingBlock(givenPosition + perpendVec, givenVector, throwTime + 0.0625f);
			CreateBouncingBlock(givenPosition - perpendVec, givenVector, throwTime + 0.0625f);
		}

		private void CreateBouncingBlock(Vector2 givenPosition, Vector2 givenVector, float givenTime)
		{
			parent.currentCB = parent.CreateCoffinBlock(givenPosition, givenPosition, initThrow: false);
			parent.currentCB.rotateSprite = true;
			parent.currentCB.rotationCount = 4f;
			parent.currentCB.baseFlightTime = givenTime;
			parent.currentCB.ThrowToTargetVector(givenPosition + givenVector * 1.5f);
			parent.currentCB.baseFlightTime = 0.15f;
			parent.currentCB.throwHeight = 2.5f;
			parent.currentCB.rotateSprite = true;
			parent.currentCB.rotationCount = 0.5f;
			parent.currentCB.jumpCountMax = maxBounceCount;
			parent.currentCB.jumpVector = givenVector;
			parent.currentCB.jumpInterval = 0f;
			parent.currentCB.jumpRange = 2.5f;
		}
	}

