		private int attackDisableStopwatchID;

		private new float exitTime = 1.75f;

		private new int exitStopwatchID;

		private CastingCircle castingCircle;

		private float startScale;

		private float endScale = 1f;

		private float castTimeToChargeTimeRatio = 0.6f;

		public new SuperMovingStatue parent;

		public GroundSlamState(string newName, FSM newFSM, SuperMovingStatue newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
