		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.anim.Play("GroundSlam", -1, 0f);
			chargeStopwatchID = ChaosStopwatch.Begin(chargeTime);
			attackDisableStopwatchID = ChaosStopwatch.Begin(chargeTime + attackDisableTime);
			exitStopwatchID = ChaosStopwatch.Begin(chargeTime + attackDisableTime + exitTime);
			slammed = false;
			castingCircle = CastingCirclePool.Spawn("Draw", parent.transform.position, parentObj: parent.gameObject, unitSizeY: startScale, color: CastingCircle.enemyColor, drawTime: chargeTime * castTimeToChargeTimeRatio, disableWithParentVal: true, trackParentVal: true, useCastTimeVal: false, castTimeVal: 0f, unitSizeX: startScale);
			SoundManager.PlayAudioWithDistance("MovingStatueRoar", parent.transform.position);
			SoundManager.PlayAudioWithDistance("EarthChargeUp", parent.transform.position);
		}

		public override void Update()
		{
			if (!slammed)
			{
				if (ChaosStopwatch.Check(chargeStopwatchID))
				{
					slammed = true;
					parent.dustEmitter.EmitCircle(200);
					CameraController.ShakeCamera();
					parent.groundSlamAttackBox.SetAttackInfo(parent.skillCategory, skillID);
					parent.groundSlamAttackBox.collider.enabled = true;
					parent.groundSlamAttackBox.transform.position = parent.transform.position;
					parent.anim.Play("GroundSlam", -1, 0.5f);
					if (castingCircle != null)
					{
						castingCircle.Reset();
					}
					Globals.ChaosInst<Explosion>(Explosion.Prefab, parent.transform.parent, parent.transform.position).Explode(2f);
					string audioID = "MeteorExplosion";
