	public class SuperLancerRainLanceState : SkillState
	{
		protected Vector2 startLocation;

		protected Vector2 jumpLocation;

		protected bool hasJumped;

		protected bool hasLanded;

		private Vector2 perpendVector;

		private Vector2 targetLinePosition;

		private BoolVarStatMod airborneStatMod;

		public new SuperLancer parent;

		public SuperLancerRainLanceState(string newName, FSM newFSM, SuperLancer newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			disablePowerUpEffect = true;
			useTargetHurtBox = false;
			airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 3);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.lanceList.Clear();
			parent.movement.EndMovement();
			parent.anim.Play("JumpWindup");
			SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
			startLocation = parent.transform.position;
			jumpLocation = (Vector2)parent.transform.position + targetVector * 5f * 2.5f;
			ThrownItem throwScript = parent.throwScript;
			throwScript.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(throwScript.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
			windupTime = StdWindupTime * 1.25f;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			exitTime = 0.75f;
			CreateAttack(startLocation);
			hasJumped = false;
			hasLanded = false;
		}

		public override void Update()
		{
			if (!hasJumped)
			{
				if (ChaosStopwatch.Check(windupStopwatchID))
				{
					hasJumped = true;
					CameraController.ShakeCamera(0.4f);
					parent.anim.Play("JumpAttack", -1, 0f);
					parent.spriteRenderer.sortingLayerName = "UI";
					parent.throwScript.ThrowToTargetVector(jumpLocation);
					SoundManager.PlayAudioWithDistance("StandardJump", parent.transform.position);
					DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
					int particleCount = 50;
					float scale = 0.25f;
					Vector3? emitPosition = parent.transform.position;
					poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
					ToggleObjects(status: false);
				}
			}
			else if (hasLanded && ChaosStopwatch.Check(exitStopwatchID))
			{
				ExitTransition();
			}
		}

		public override void OnExit()
		{
			if (hasJumped && !hasLanded)
			{
				OnLanding();
			}
			base.OnExit();
			ToggleObjects(status: true);
			ThrownItem throwScript = parent.throwScript;
			throwScript.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(throwScript.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		}

		public override void ExitTransition()
		{
			base.ExitTransition();
			parent.AllowHurtState(status: false);
		}

		public virtual void OnLanding()
		{
			hasLanded = true;
			ToggleObjects(status: true);
			exitStopwatchID = ChaosStopwatch.Begin(exitTime);
			parent.anim.Play("CrouchLand", -1, 0f);
			parent.spriteRenderer.sortingLayerName = "Actor";
			jumpLocation = parent.transform.position;
			PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, jumpLocation);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 100;
			float scale = 0.25f;
			Vector3? emitPosition = jumpLocation;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			string audioID = "GroundSlam";
			Vector2? soundOrigin = jumpLocation;
			scale = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, scale);
			parent.AllowHurtState(status: true);
			CameraController.ShakeCamera(0.5f);
		}

		public virtual void ToggleObjects(bool status)
		{
			parent.airborneStat.Modify(airborneStatMod, !status);
			parent.hurtBoxTransform.gameObject.SetActive(status);
			parent.floorContact.SetActive(status);
			parent.TogglePreventFallCollider(status);
		}

		public void CreateAttack(Vector2 givenPosition)
		{
			perpendVector = Globals.GetPerpendicular(targetVector);
			CreateLanceWave(givenPosition + targetVector, useDelay: true);
			CreateLanceWave(givenPosition + perpendVector);
			CreateLanceWave(givenPosition - perpendVector);
		}

		public void CreateLanceWave(Vector2 givenPosition, bool useDelay = false)
		{
			LanceWave lanceWave = ChaosInst<LanceWave>(LanceWave.Prefab, givenPosition);
			lanceWave.SetSkillData(parent.skillCategory, skillID);
			lanceWave.moveVector = targetVector;
			lanceWave.paletteIndex = parent.paletteIndex;
			lanceWave.initSpawnRate = windupTime + ((!useDelay) ? 0f : (lanceWave.spawnRate * 0.5f));
			parent.lanceList.Add(lanceWave.gameObject);
		}
	}

	public class SuperLancerHundredLanceState : SkillState
	{
		private bool hurtStateAllowed;

		private float spreadValue = 1.25f;

		private Vector2 perpendVector;

		private Vector2 spawnPosition;

		private int stabCount = 15;

		private float stabInterval = 0.05f;

		private int stabStopwatchID;

		private bool stabComplete;

		private LanceStab currentLS;

		private Vector2 targetLinePosition;

		private int attackStopwatchID;

		private bool attackCompleted;

		private ChaosQuickStopwatch initialAttackTimer;

		private bool initialAttackStarted;

		public new SuperLancer parent;

		public SuperLancerHundredLanceState(string newName, FSM newFSM, SuperLancer newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			usePowerUpEffect = false;
			castingAnimName = "Attack";
			initialAttackTimer = new ChaosQuickStopwatch();
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.lanceList.Clear();
			parent.FaceTarget(parent.closestTargetInfo.hurtBoxTransform.position, 4, useHurtBox: true);
			parent.attack.transform.localEulerAngles = Globals.GetRotationVector((parent.closestTargetInfo.hurtBoxTransform.position - parent.hurtBoxTransform.position).normalized) * ((!parent.isFacingRight) ? (-1f) : 1f);
			parent.anim.PlayDirectional(castingAnimName + parent.facingDirection);
			SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
			windupTime = StdWindupTime * 1.25f;
			ChaosStopwatch.Stop(windupStopwatchID);
			stabStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, stabInterval, stabCount);
			perpendVector = Globals.GetPerpendicular(targetVector);
			stabComplete = false;
			attackCompleted = false;
			initialAttackStarted = false;
			hurtStateAllowed = false;
			parent.movement.MoveToTarget((Vector2)parent.transform.position - targetVector * 0.15f);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 180;
			float scale = 0.3f;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitCircle(particleCount, scale, 14f, -1f, emitPosition);
		}

		public override void ExecuteSkill()
		{
			if (!stabComplete)
			{
				if (initialAttackStarted && !initialAttackTimer.IsRunning)
				{
					parent.anim.PlayDirectional("Attack" + parent.facingDirection, -1, 1f);
					CameraController.ShakeCamera(0.3f);
					parent.movement.MoveToTarget((Vector2)parent.transform.position + targetVector * 4f);
				}
				switch (ChaosStopwatch.CheckInterval(stabStopwatchID))
				{
				case StopwatchState.Ready:
					spawnPosition = (Vector2)parent.hurtBoxTransform.position + perpendVector * UnityEngine.Random.Range(0f - spreadValue, spreadValue);
					CreateLanceStab(spawnPosition, targetVector, windupTime);
					if (!initialAttackStarted && !initialAttackTimer.IsRunning)
					{
						initialAttackTimer.SetDelay(windupTime);
						initialAttackTimer.IsRunning = true;
						initialAttackStarted = true;
					}
					break;
				case StopwatchState.Done:
					stabComplete = true;
					attackStopwatchID = ChaosStopwatch.Begin(windupTime + stabInterval);
					break;
				}
			}
			else if (!attackCompleted)
			{
				if (ChaosStopwatch.Check(attackStopwatchID))
				{
					attackCompleted = true;
					parent.attack.SetAttackInfo(parent.skillCategory, parent.attackSkillID);
					parent.anim.PlayDirectional("Attack" + parent.facingDirection, -1, 0.5f);
					CameraController.ShakeCamera(0.4f);
					SoundManager.PlayAudioWithDistance(parent.attackAudioID, spawnPosition);
				}
			}
			else if (!hurtStateAllowed && parent.anim.AnimPlayed(0.6f))
			{
				hurtStateAllowed = true;
				parent.AllowHurtState(status: true);
				base.ExecuteSkill();
			}
		}

		public override void ExitTransition()
		{
			base.ExitTransition();
			parent.AllowHurtState(status: false);
		}

		private void CreateLanceStab(Vector2 givenPosition, Vector2 givenVector, float givenDelay)
		{
			currentLS = ChaosInst<LanceStab>(LanceStab.Prefab, givenPosition, Globals.GetRotationQuaternion(givenVector));
			currentLS.attack.SetAttackInfo(parent.skillCategory, skillID);
			currentLS.attack.knockbackOverwriteVector = targetVector;
			currentLS.paletteIndex = parent.paletteIndex;
			currentLS.attackDelay = givenDelay;
			parent.lanceList.Add(currentLS.gameObject);
		}
	}

