		private Vector2 perpendVec;

		private int finalStopwatchID;

		private bool shotCompleted;

		public new SuperMage parent;

		public SuperMageQuickShotState(string newName, FSM newFSM, SuperMage newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			disablePowerUpEffect = true;
			castingAnimName = "Backhand";
			spawnRange = 1.5f;
			castTime = 0f;
			holdTime = 0f;
			trackTarget = false;
		}

		public override void OnEnter()
		{
			finalShot = repeatCounter >= repeatCountMax;
			shotCompleted = false;
			base.OnEnter();
			parent.AllowHurtState(status: false);
			SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
		}

		public override bool CreateAllProjectiles()
		{
			perpendVec = Globals.GetPerpendicular(targetVector);
			for (int i = -2; i <= 2; i++)
			{
				projectileList.Add(CreateProjectile(Globals.GetRotatedCircleVector(totalPositionCount, i, targetVector)));
			}
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 30;
			float z = Globals.GetRotationVector(-targetVector).z;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitDirBurst(particleCount, z, -1f, -1f, -1f, emitPosition);
			CameraController.ShakeCamera(0.3f);
			return true;
		}

		public override Projectile CreateProjectile(Vector2 givenVector)
		{
			Projectile projectile = ChaosInst<Projectile>(projectilePrefab, (Vector2)parent.hurtBoxTransform.position + givenVector * spawnRange, Globals.GetRotationQuaternion(targetVector));
			projectile.parentObject = parent.gameObject;
			projectile.parentEntity = parent;
			projectile.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			projectile.attackBox.knockbackOverwriteVector = targetVector;
			projectile.attackBox.collider.enabled = false;
			projectile.moveVector = targetVector;
			originalMoveSpeed = projectile.moveSpeed;
			projectile.moveSpeed = 0f;
			projectile.projectileSpriteRenderer.material.SetFloat("_PaletteIndex", 3f);
			projectile.anim.Play("Spawn");
			string audioID = "MageFireballForm";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			projectile.Show();
			return projectile;
		}

		public override void ExtraFireSettings(Projectile givenProj)
		{
			givenProj.flyTime = 4f;
			givenProj.RefreshFlightTime();
			string audioID = "MageFireballRelease";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}

		public override void ExitTransition()
		{
			if (finalShot)
			{
				if (!shotCompleted)
				{
					shotCompleted = true;
					repeatCounter = 0;
					parent.anim.Play("Idle");
					parent.AllowHurtState(status: true);
					finalStopwatchID = ChaosStopwatch.Begin(StdExitTime * 4f);
				}
				if (ChaosStopwatch.Check(finalStopwatchID))
				{
					parent.AllowHurtState(status: false);
					base.ExitTransition();
				}
			}
			else
			{
				repeatCounter++;
				if (parent.teleportState.LocationIsReady())
				{
					fsm.ChangeState(parent.teleportState.name);
				}
				else
				{
					finalShot = true;
				}
			}
		}
	}

