	public class SuperRogueHurtState : MiniBossHurtState
	{
		public new SuperRogue parent;

		public SuperRogueHurtState(string newName, FSM newFSM, SuperRogue newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}

		public override void OnEnter()
		{
			if (fsm.previousStateName != name)
			{
				if (parent.stealthState != null && parent.IsStealthed)
				{
					parent.stealthState.EndStealth();
				}
				if (parent.teleportState != null && parent.teleportState.IsReady() && Vector2.Distance(parent.closestTargetInfo.position, parent.transform.position) >= parent.teleportState.minActivationRadius)
				{
					fsm.ChangeState(parent.teleportState.name);
					parent.AllowHurtState(status: false, skipBreakEffect: true);
					return;
				}
			}
			base.OnEnter();
		}

		public override void HandleDurationIncrease(bool first = false)
		{
			base.HandleDurationIncrease(first);
			if (first)
			{
				parent.DestroyClones();
			}
		}
	}

	public class SuperRogueDeadState : MiniBossDeadState
