	public class SuperRogueAttackState : AttackStateRotational
	{
		private bool hurtStateAllowed;

		private bool firstFrame;

		public bool stealthAttack;

		public new SuperRogue parent;

		public SuperRogueAttackState(string newName, FSM newFSM, SuperRogue newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			hurtStateAllowed = false;
			firstFrame = true;
		}

		public override void Update()
		{
			base.Update();
			if (firstFrame)
			{
				firstFrame = false;
			}
			else if (!hurtStateAllowed && parent.anim.AnimPlayed(0.8f))
			{
				hurtStateAllowed = true;
				parent.AllowHurtState(status: true, stealthAttack);
			}
		}

		public override void ExitTransition()
		{
			if (parent.anim.AnimPlayed(2f))
			{
				SuperRogue superRogue = parent;
				bool status = false;
				bool skipOutline = parent.fsm.nextStateName.Contains("Stealth");
				superRogue.AllowHurtState(status, skipBreakEffect: false, skipOutline);
				base.ExitTransition();
			}
		}

		public override void OnExit()
		{
			stealthAttack = false;
			base.OnExit();
		}
	}

	public class SuperRogueStealthState : StealthState
	{
		private int cloneCount = 3;

		private Vector2 spawnPosition;

		public new SuperRogue parent;

		public SuperRogueStealthState(string newName, FSM newFSM, SuperRogue newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			requireLineOfSight = false;
			castingAnimName = "Stealth";
			parentSprite = parent.spriteRenderer;
			stealthDuration = 60f;
		}

		public override bool IsReady()
		{
			return !parent.IsStealthed && base.IsReady();
		}

		public override void OnEnter()
		{
			if (parent.IsStealthed)
			{
				StartCooldown();
				ExitTransition();
				return;
			}
			base.OnEnter();
			prevOutlineColor = Color.clear;
			SoundManager.PlayAudioWithDistance("RogueStealth", parent.transform.position);
			if (parent.regenState.IsReady())
			{
				cloneCount = 4;
				parent.maxCloneCount = 4;
			}
			else
			{
				cloneCount = 3;
				parent.maxCloneCount = 3;
			}
			int num = 3;
			int num2 = cloneCount * num;
			int num3 = Random.Range(0, num2);
			Enemy.PlayTeleportSmokeEffect(parent.transform.position);
			for (int i = 0; i < num2; i += num)
			{
				spawnPosition = (Vector2)parent.myOrigin + Globals.GetCirclePositionVector(num2, i + num3) * 10f;
				spawnPosition = Globals.GetLinecastVector(parent.myOrigin, spawnPosition, ChaosCollisions.layerAllWallAndObst);
				if (i == 0)
				{
					parent.transform.position = spawnPosition;
					Enemy.PlayTeleportSmokeEffect(parent.transform.position);
				}
				else
				{
					parent.SummonClone(spawnPosition, "Stealth");
				}
			}
		}

		public override void ExitTransition()
		{
			if (parent.regenState.IsReady())
			{
				fsm.ChangeState(parent.regenState.name);
			}
			else
			{
				base.ExitTransition();
			}
		}

		public override void ToggleStealth(bool status = false, bool ignoreFlash = false)
		{
			base.ToggleStealth(status, ignoreFlash);
			parent.AllowHurtState(status: true, fsm.currentStateName.Contains("Attack") || fsm.currentStateName.Contains("Hurt"), status || fsm.currentStateName.Contains("Hurt") || fsm.currentStateName.Contains("Dead"));
			if (status)
			{
				parent.auraEmitter.Stop();
				parent.auraEmitter.Clear();
				return;
			}
			parent.StartAura();
			if (parent.fsm.currentState == parent.attackState)
			{
				parent.attackState.stealthAttack = true;
			}
		}
	}

	public class SuperRogueTeleportState : RandomTeleportState
	{
		private Vector2 initVector;

		private Vector2 perpendVector;

		public new SuperRogue parent;

		public SuperRogueTeleportState(string newName, FSM newFSM, SuperRogue newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			exitTime = 0.25f;
			spawnInitialPortal = false;
		}

		public override void OnEnter()
		{
			Enemy.PlayTeleportSmokeEffect(parent.transform.position);
			parent.UpdateTargetInfo();
			base.OnEnter();
			parent.anim.Play("Charging");
			targetPosition = parent.closestTargetInfo.position;
			parent.AllowHurtState(status: false, skipBreakEffect: true, skipOutline: true);
		}

		public override void ExitTransition()
		{
			SummonLungeClones();
			fsm.ChangeState("SuperRogueShuriken");
		}

		public void SummonLungeClones()
		{
			initVector = (targetPosition - (Vector2)parent.transform.position).normalized;
			perpendVector = Globals.GetPerpendicular(initVector);
			parent.SummonClone(Globals.GetLinecastVector(targetPosition, targetPosition + perpendVector * teleportRange, ChaosCollisions.layerAllWallAndObst), "Lunge");
			parent.SummonClone(Globals.GetLinecastVector(targetPosition, targetPosition - perpendVector * teleportRange, ChaosCollisions.layerAllWallAndObst), "Lunge");
		}
	}

	public class SuperRogueShurikenState : SkillState
	{
		private Vector2 perpendVector;

		public new SuperRogue parent;

		public SuperRogueShurikenState(string newName, FSM newFSM, SuperRogue newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			disablePowerUpEffect = true;
			castingAnimName = "Backhand";
			exitTime = 1f;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime * 1.25f);
			SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
		}

		public override void WindupUpdate()
		{
			parent.anim.Play(castingAnimName, -1, 0f);
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			parent.AllowHurtState(status: true);
			parent.anim.Play(castingAnimName, -1, 0.5f);
			perpendVector = Globals.GetPerpendicular(targetVector);
			ThrowShuriken(targetVector);
			ThrowShuriken((targetVector + perpendVector).normalized);
			ThrowShuriken((targetVector - perpendVector).normalized);
		}

		private void ThrowShuriken(Vector2 givenVector)
		{
			Shuriken shuriken = ChaosInst<Shuriken>(Shuriken.Prefab, parent.hurtBoxTransform.position);
			shuriken.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			shuriken.moveVector = givenVector;
			if (parent.closestTargetInfo != null)
			{
				shuriken.targetTrans = parent.closestTargetInfo.hurtBoxTransform;
			}
		}

		public override void ExitTransition()
		{
			base.ExitTransition();
			parent.AllowHurtState(status: false);
		}
	}

