	public Rogue SummonClone(Vector2 givenPosition, string givenStateName = "")
	{
		cloneList.RemoveNullValues();
		Rogue rogue;
		if (cloneList.Count < maxCloneCount)
		{
			rogue = (Rogue)Enemy.Spawn(EName.Rogue, givenPosition, transform.parent, dropLoot: false, alerted: true, spawnCard: false, survivalMode: true, overrideCountDeath: true);
			rogue.health.healthStat.AddMod(cloneHealthMod);
			rogue.summoned = true;
			rogue.closestTargetInfo = closestTargetInfo;
			cloneList.Add(rogue);
		}
		else
		{
			rogue = cloneList[0];
			cloneList.Remove(rogue);
			cloneList.Add(rogue);
			Enemy.PlayTeleportSmokeEffect(rogue.transform.position);
			rogue.transform.position = givenPosition;
		}
		Enemy.SpawnEnemyPortal(givenPosition);
		if (givenStateName != string.Empty)
		{
			if (givenStateName == "Lunge" && rogue.stealthState != null && rogue.IsStealthed)
			{
				rogue.stealthState.EndStealth();
			}
			rogue.fsm.QueueChangeState(givenStateName);
		}
		return rogue;
	}

	public void DestroyClones()
	{
		foreach (Rogue clone in cloneList)
		{
			clone.stealthState.prevFlashColor = Color.white;
			clone.stealthState.prevFlashAmount = 0f;
			clone.stealthState.ignoreFlashAlteringStates = true;
			clone.stealthState.EndStealth();
			clone.fsm.QueueChangeState("Dead");
		}
	}
