			: base(newName, newFSM, newEnt)
		{
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.health.shieldStat.CurrentValue = 0f;
		}

		public override void HandleDurationIncrease(bool first = false)
		{
			if (first)
			{
				hitCounter = 1;
				hurtStopwatchID = ChaosStopwatch.Begin(baseHurtDuration * 3f);
				return;
			}
			if (lastAttackInfo != null && !lastAttackInfo.isStatusEffect)
			{
				hitCounter++;
			}
			hurtStopwatchID = ChaosStopwatch.Begin(Mathf.Min(maxHurtDuration, durationIncreaseMultiplier * baseHurtDuration / (float)hitCounter + ChaosStopwatch.GetRemainingTime(hurtStopwatchID)));
		}
	}

	public class SuperSummonerSummonState : SummonState
	{
		private int maxMinionPerCast = 7;

		private int currentSpawnCount;

		private int currentSpawnIndex;

		private List<Entity> rvList = new List<Entity>();

		private int maxRVCount = 3;

		private List<Entity> shList = new List<Entity>();

		private int maxSHCount = 3;

		private OrbFamiliar currentOC;

		public new SuperSummoner parent;

		public SuperSummonerSummonState(string newName, FSM newFSM, SuperSummoner newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
		{
			parent = newEnt;
			usePowerUpEffect = false;
			maxMinionCount = 12;
			healthValue = 25;
			castingAnimName = "Charging";
			spawnRange = 6f;
			useCDResetTime = false;
			minions = parent.orbChList;
			healthMod.modValue = Mathf.Min(100, 25 + 25 * parent.CurrentDifficulty);
		}

		public override void Update()
		{
			if (parent.regenState.IsReady())
			{
				fsm.ChangeState(parent.regenState.name);
			}
			else
			{
				base.Update();
			}
		}

		public override void SummonEnemies()
		{
			currentPosition = parent.transform.position;
			currentSpawnCount = Mathf.Min(maxMinionCount - curMinionCount, maxMinionPerCast);
			if (currentSpawnCount == 1 || currentSpawnCount % 2 == 0)
			{
				currentSpawnIndex = 1;
				currentSpawnCount++;
			}
			for (int i = currentSpawnIndex; i < currentSpawnCount; i++)
			{
				spawnPosition = Globals.GetLinecastVector(currentPosition, currentPosition + Globals.GetCirclePositionVector(currentSpawnCount, i) * spawnRange, ChaosCollisions.layerAllWallAndObst);
				SummonOrbFamiliar(EName.OrbChargeFamiliar, spawnPosition, minions);
			}
			if (parent.CurrentDifficulty > 0)
			{
				currentSpawnCount = maxRVCount - rvList.Count;
				for (int j = 0; j < currentSpawnCount; j++)
				{
					spawnPosition = Globals.GetLinecastVector(currentPosition, currentPosition + Globals.GetRotatedCircleVector(currentSpawnCount, j, Vector2.down) * 3f, ChaosCollisions.layerAllWallAndObst);
					SummonOrbFamiliar(EName.OrbRevolveFamiliar, spawnPosition, rvList);
				}
			}
			if (parent.CurrentDifficulty > 1)
			{
				currentSpawnCount = maxSHCount - shList.Count;
				for (int k = 0; k < currentSpawnCount; k++)
				{
					spawnPosition = Globals.GetLinecastVector(currentPosition, currentPosition + Globals.GetCirclePositionVector(currentSpawnCount, k) * 3.75f, ChaosCollisions.layerAllWallAndObst);
					SummonOrbFamiliar(EName.OrbShootFamiliar, spawnPosition, shList);
				}
			}
			SoundManager.PlayAudioWithDistance("EnemyCast", currentPosition);
		}

		private void SummonOrbFamiliar(EName givenEName, Vector2 givenPos, List<Entity> givenList)
		{
			currentOC = (OrbFamiliar)Enemy.Spawn(givenEName, givenPos, parent.transform.parent, dropLoot: false, alerted: true, spawnCard: true, survivalMode: false, overrideCountDeath: true);
			Health health = currentOC.health;
			health.deathEventHandlers = (Health.DeathEventHandler)Delegate.Remove(health.deathEventHandlers, new Health.DeathEventHandler(RemoveMinion));
			Health health2 = currentOC.health;
			health2.deathEventHandlers = (Health.DeathEventHandler)Delegate.Combine(health2.deathEventHandlers, new Health.DeathEventHandler(RemoveMinion));
			currentOC.health.healthStat.AddMod(healthMod);
			currentOC.parentSummoner = parent.gameObject;
			currentOC.summoned = true;
			if (currentOC.attack != null)
			{
				currentOC.attack.SetAttackInfo(parent.skillCategory, skillID);
			}
			parent.nearbyEnemyList.Add(currentOC);
			givenList.Add(currentOC);
			if (parentSummonsList != null)
			{
				parentSummonsList.Add(currentOC);
			}
		}

		public override void RemoveMinion(Entity entityScript)
		{
			base.RemoveMinion(entityScript);
			rvList.Remove(entityScript);
			shList.Remove(entityScript);
			if (parentSummonsList != null && parentSummonsList.Count == 0 && parent != null && parent.health.CurrentHealthValue > 0)
			{
				parent.health.lastAttack = null;
				parent.AllowHurtState(status: true);
				fsm.QueueChangeState("Hurt", allowSelfTransition: true);
			}
		}
	}

	public class SuperSummonerAttackState : Summoner.SummonerSpreadShotState
	{
		private bool vulQueued;

		private float vulDuration = 1f;

		private int vulStopwatchID;

		private bool fireEffectPlayed;

		public new SuperSummoner parent;

		public SuperSummonerAttackState(string newName, FSM newFSM, SuperSummoner newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			usePowerUpEffect = false;
			totalPositionCount = 12;
			projectileCount = 3;
			waveCount = 1;
		}

		public override void OnEnter()
		{
			fireEffectPlayed = false;
			vulQueued = false;
			parent.AllowHurtState(status: false);
			exitTime = 0f;
			base.OnEnter();
			foreach (Entity orbCh in parent.orbChList)
			{
				if (orbCh != null && orbCh is OrbChargeFamiliar)
				{
					((OrbChargeFamiliar)orbCh).QueueAttackState();
				}
			}
			SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			if (!fireEffectPlayed && projectilesFired)
			{
				DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
				int particleCount = 30;
				float z = Globals.GetRotationVector(-targetVector).z;
				Vector3? emitPosition = parent.transform.position;
				poolItem.EmitDirBurst(particleCount, z, -1f, -1f, -1f, emitPosition);
				CameraController.ShakeCamera(0.3f);
				fireEffectPlayed = true;
			}
		}

		public override void ExitTransition()
		{
			if (!vulQueued)
			{
				vulQueued = true;
				parent.AllowHurtState(status: true);
				vulStopwatchID = ChaosStopwatch.Begin(vulDuration);
			}
			else if (ChaosStopwatch.Check(vulStopwatchID))
			{
				parent.AllowHurtState(status: false);
				base.ExitTransition();
			}
		}
	}

