		});
		if (isFinalRoom)
		{
			fsm.AddState(new MiniBossLaserSummonState(fsm, this, "Charging"));
		}
		fsm.AddState(new SuperSummonerHurtState("Hurt", fsm, this));
		fsm.AddState(new SuperSummonerDeadState("Dead", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}

