using UnityEngine;

public class ZoneEnemy : Enemy
{
	public class ZoneIdleState : State<ZoneEnemy>
	{
		public ChaosQuickStopwatch checkQSW;

		public bool firstUpdate = true;

		public virtual bool TargetFound => parent.UpdateTargetInfo() != null;

		public ZoneIdleState(string newName, FSM newFSM, ZoneEnemy newEnt)
			: base(newName, newFSM, newEnt)
		{
			checkQSW = new ChaosQuickStopwatch(Random.Range(0.75f, 1f));
		}

		public override void OnEnter()
		{
			parent.anim.Play("Idle", -1, 0f);
		}

		public override void Update()
		{
			if (checkQSW.IsRunning)
			{
				return;
			}
			checkQSW.IsRunning = true;
			if (TargetFound)
			{
				if (firstUpdate || parent.isStationary)
				{
					fsm.ChangeState("Attack");
				}
				else
				{
					fsm.ChangeState("Reposition");
				}
			}
			firstUpdate = false;
		}
	}

	public class ZoneRepositionState(string newName, FSM newFSM, ZoneEnemy newEnt) : State<ZoneEnemy>(newName, newFSM, newEnt)
	{
		public Vector2 targetLocation;

		public float maxRange = 6f;

		public override void OnEnter()
		{
			parent.anim.Play("Run", -1, 0f);
			targetLocation = Globals.GetLinecastVector(parent.transform.position, (Vector2)parent.myOrigin + Random.insideUnitCircle * maxRange, parent.lineOfSightLayerMask);
			parent.FaceTarget(targetLocation, 2);
		}

		public override void FixedUpdate()
		{
			if (parent.movement.MoveToTarget(targetLocation, 1f))
			{
				fsm.ChangeState("Attack");
			}
		}
	}

	public class ZoneAttackState(string newName, FSM newFSM, ZoneEnemy newEnt) : State<ZoneEnemy>(newName, newFSM, newEnt)
	{
		public int enterStopwatchID;

		public int exitStopwatchID;

		public bool freezeAnimOnWindup = true;

		public bool atkCompleted;

		public virtual float EnterTime => (!parent.isStationary) ? Random.Range(0.5f, 0.75f) : Random.Range(0.125f, 0.5f);

		public virtual float ExitTime => (!parent.isStationary) ? Random.Range(1f, 1.25f) : Random.Range(0.5f, 0.75f);

		public override void OnEnter()
		{
			parent.anim.Play("Attack", -1, 0f);
			enterStopwatchID = ChaosStopwatch.Begin(EnterTime);
			atkCompleted = false;
		}

		public override void Update()
		{
			if (!ChaosStopwatch.Check(enterStopwatchID))
			{
				if (freezeAnimOnWindup)
				{
					parent.anim.Play("Attack", -1, 0f);
				}
			}
			else if (!atkCompleted)
			{
				ExecuteAttack();
			}
			else if (ChaosStopwatch.Check(exitStopwatchID))
			{
				parent.fsm.ChangeState("Idle");
			}
		}

		public virtual void ExecuteAttack()
		{
			atkCompleted = true;
			exitStopwatchID = ChaosStopwatch.Begin(ExitTime);
		}
	}

