			currentAC = Globals.ChaosInst<Arrow>(Arrow.Prefab, null, (Vector2)parent.atkTrans.position + givenVector * 0.5f, Globals.GetRotationQuaternion(givenVector));
			currentAC.parentObject = parent.gameObject;
			currentAC.parentEntity = parent;
			currentAC.attackBox.SetAttackInfo(parent.skillCategory, "WindZoneAttack");
			currentAC.attackBox.knockbackOverwriteVector = givenVector;
			currentAC.moveVector = givenVector;
			currentAC.flyTime = 0.25f;
			currentAC.moveSpeed = 20f;
	public class WindZoneHurtState : ZoneHurtState
		public WindZoneHurtState(string newName, FSM newFSM, ZoneEnemy newEnt)
			: base(newName, newFSM, newEnt)
		public override void PlayHurtAudio()
			float overridePitch = Random.Range(0.5f, 0.6f);
			soundOrigin = parent.transform.position;
	public class WindZoneDeadState : ZoneDeadState
		public WindZoneDeadState(string newName, FSM newFSM, WindZoneEnemy newEnt)
			: base(newName, newFSM, newEnt)
		public override void OnEnter()
			base.OnEnter();
			int? particleCount2 = 1;
			Vector3? localEulerAngles = new Vector3(0f, 0f, Random.Range(-10f, 10f));
			particleCount2 = 1;
			localEulerAngles = parent.transform.position + Vector3.up;
			particleCount2 = 1;
			localEulerAngles = new Vector3(0f, 0f, Random.Range(-190f, -170f));
		public override void PlayDeadAudio()
			base.PlayDeadAudio();
	[HideInInspector]
	public ParticleSystem windPartSys;
	private ParticleSystem attackEffect0;
	private ParticleSystem attackEffect1;
	private Transform attackEffectTrans;
	public override void Awake()
		disablePreventFallCollider = true;
		base.Awake();
		windPartSys = transform.Find("WindPartSys").GetComponent<ParticleSystem>();
		attackEffectTrans = transform.Find("AttackEffect");
		attackEffect0 = attackEffectTrans.Find("SpinEffectTop").GetComponent<ParticleSystem>();
		attackEffect1 = attackEffectTrans.Find("SpinEffectBot").GetComponent<ParticleSystem>();
	public override void InitFSM()
		base.InitFSM();
		fsm.ReplaceState(new WindZoneRepositionState("Reposition", fsm, this));
		fsm.AddState(new WindZoneAttackState("Attack", fsm, this));
		fsm.ReplaceState(new WindZoneHurtState("Hurt", fsm, this));
		fsm.ReplaceState(new WindZoneDeadState("Dead", fsm, this));
	public override void Start()
		base.Start();
		traversableNodeMap = Pathfinder.connectedNodeMap;
		lineOfSightLayerMask = ChaosCollisions.layerAllWallAndObst;

