		private Vector2 attackVector;

		private NumVarStatMod moveSpeedMod = new NumVarStatMod("AtkSpeedMod", 12f, 10, VarStatModType.Override);

		private ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch(3f);

		public override void OnEnter()
		{
