		}

		public override void OnExit()
		{
			Attack attack = parent.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			parent.movement.moveSpeedStat.Modify(moveSpeedMod, addMod: false);
		}

		private void OnTargetHit(Entity givenEntity)
		{
			if (givenEntity != null && !(givenEntity is Destructible))
			{
				targetStopwatch.IsRunning = true;
			}
			parent.closestTargetInfo = null;
			if (!audioStopwatch.IsRunning)
			{
				audioStopwatch.IsRunning = true;
				SoundManager.PlayWithDistAndSPR("AquaWhoosh", parent.transform.position);
			}
		}

		private Vector2 GetAttackVector()
		{
			if (parent.closestTargetInfo == null || parent.closestTargetInfo.hurtBoxTransform == null)
			{
				return Vector2.zero;
			}
			attackVector = (parent.closestTargetInfo.hurtBoxTransform.position - parent.transform.position).normalized;
			return attackVector;
		}
	}

