	fsm.AddState(new IdleState("Idle", fsm, this));
	fsm.AddState(new AttackState("Attack", fsm, this));
	fsm.AddState(new DeadState("Dead", fsm, this));
	fsm.ChangeState(fsm.defaultStateName);
	currentVector = Vector2.zero;
}
public void Initialize(Transform givenTransform, List<GameObject> givenGroup, Vector2 givenVector, bool givenFlip, bool givenEmpowered)
{
	followTrans = givenTransform;
	targetGroup = givenGroup;
	arcFlip = givenFlip;
	if (givenEmpowered)
	{
		atkSegCount += 2;
	}
	currentVector = givenVector;
	SetTargetVector(currentVector);
	spriteTrans.localEulerAngles = Globals.GetRotationVector(currentVector);
}
private void Start()
{
	atkTransArr = new Tuple<Transform, Attack>[atkSegCount];
	atkPosAndDirArr = new Tuple<Vector2, Vector2>[atkSegCount + 1];
	Vector2 vector = transform.position;
	for (int i = 0; i < atkSegCount + 1; i++)
	{
		atkPosAndDirArr[i] = new Tuple<Vector2, Vector2>(vector, currentVector);
		if (i != atkSegCount)
		{
			Attack attack = Globals.ChaosInst<Attack>(this.attack.gameObject, transform, vector);
			attack.ChangeAttackInfoLevel(2);
			attack.gameObject.AddComponent<Rigidbody2D>();
			attack.gameObject.SetActive(value: false);
			atkTransArr[i] = new Tuple<Transform, Attack>(attack.transform, attack);
		}
	}
	atkStopwatch.IsRunning = true;
	lifeStopwatchID = ChaosStopwatch.Begin(lifeTime + UnityEngine.Random.value);
}
private TargetInfo UpdateTargetInfo()
{
	if (followTrans == null)
	{
		return null;
	}
	closestTargetInfo = Entity.GetClosestTarget(targetGroup, followTrans.position, targetRange, playerTagOnly: false, null, gameObject, requireLOS: true, ChaosCollisions.layerUpperWall);
	return closestTargetInfo;
}
private void SetTargetVector(Vector2 givenVector)
{
	targetVector = givenVector;
	retargetStopwatch.IsRunning = true;
}
private void MoveToVector(Vector2? givenVector = null)
{
	if (retargetStopwatch.IsRunning)
	{
		currentVector = Vector2.Lerp(currentVector, targetVector, targetSpeed * Time.fixedDeltaTime).normalized;
		arcVector = Globals.GetPerpendicular(currentVector, arcFlip);
	}
	else if (givenVector.HasValue)
	{
		currentVector = Vector2.Lerp(currentVector, givenVector.Value, targetSpeed * Time.fixedDeltaTime).normalized;
		arcVector = Globals.GetPerpendicular(currentVector, arcFlip);
	}
	arcLerpValue = Mathf.PingPong(arcStopwatch.TimePercentage * 2f, 1f);
	arcVector = Vector2.Lerp(Vector2.zero, arcVector, arcLerpValue) * 0.707f;
	if (!arcStopwatch.IsRunning)
	{
		arcStopwatch.IsRunning = true;
		arcFlip = !arcFlip;
	}
	movement.moveVector = (currentVector + arcVector).normalized;
	movement.MoveToMoveVector();
	attack.knockbackOverwriteVector = movement.moveVector;
	if (!moveVecSet)
	{
		moveVecSet = true;
	}
}
private void Update()
{
	if (fsm != null)
	{
		fsm.currentState.Update();
	}
}
private void FixedUpdate()
{
	if (fsm != null)
	{
		fsm.currentState.FixedUpdate();
	}
}
