using UnityEngine;

public class ChessPiece : Entity
{
	public class SpawnState : State<ChessPiece>
	{
		private int delayStopwatchID;

		private bool animPlayed;

		private bool firstFrame;

		public SpawnState(string newName, FSM newFSM, ChessPiece newEnt)
			: base(newName, newFSM, newEnt)
		{
		}

		public override void OnEnter()
		{
			parent.anim.Play("Spawn", -1, 0f);
			animPlayed = false;
			firstFrame = true;
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(parent.debrisType, 15, parent.transform.position, RockDebrisEmitter.SmallCircleExplosionOverride);
			CameraController.ShakeCamera(1f, ignoreShakeCount: true);
		}

		public override void Update()
		{
			if (firstFrame)
			{
				firstFrame = false;
			}
			else if (animPlayed)
			{
				if (ChaosStopwatch.Check(delayStopwatchID))
				{
					fsm.ChangeState("Jump");
				}
			}
			else if (parent.anim.AnimPlayed())
			{
				animPlayed = true;
				delayStopwatchID = ChaosStopwatch.Begin(parent.spawnDelay);
				parent.ToggleLayers(status: false);
			}
		}
	}

