	{
		private bool landed;

		private bool landingIsSafe;

		private int delayStopwatchID = -1;

		public JumpState(string newName, FSM newFSM, ChessPiece newEnt)
			: base(newName, newFSM, newEnt)
	public class IdleState : State<ChessPiece>
	{
		private new ChessPiece parent;

		private int delayStopwatchID = -1;

		public IdleState(string stateName, FSM parentFSM, ChessPiece parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
			parent = parentEntity;
		}

		public override void OnEnter()
		{
			GameController.allies.Add(parent.gameObject);
			if (parent.isEmpowered)
			{
				parent.empoweredJump = !parent.empoweredJump;
				if (parent.empoweredJump)
				{
					parent.landingPosition = parent.transform.position;
					parent.thrownItem.throwHeight *= 0.75f;
					delayStopwatchID = ChaosStopwatch.Begin(parent.destroyDelay * 0.5f);
				}
			}
			else
			{
				delayStopwatchID = ChaosStopwatch.Begin(parent.destroyDelay);
			}
		}

		public override void Update()
		{
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				if (parent.empoweredJump)
				{
					fsm.ChangeState("Jump");
				}
				else if (parent.gameObject != null)
				{
					string audioID = "RockExplode";
					Vector2? soundOrigin = parent.transform.position;
					float standardPitchRange = SoundManager.StandardPitchRange;
					SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
					UnityEngine.Object.Destroy(parent.gameObject);
				}
			}
		}
	}

