public class JumpState : State<ChessPiece>
{
	private bool landed;
	private bool landingIsSafe;
	private int delayStopwatchID = -1;
	public JumpState(string newName, FSM newFSM, ChessPiece newEnt)
		: base(newName, newFSM, newEnt)
	{
		ThrownItem thrownItem = parent.thrownItem;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(HandleLandingEvent));
	}
	public override void OnEnter()
	{
		parent.ToggleColliders(status: false);
		parent.anim.Play("Idle", -1, 0f);
		parent.attack.ChangeAttackInfoLevel(2);
		parent.thrownItem.ThrowToTargetVector(parent.landingPosition);
		landingIsSafe = Globals.CheckCircle(parent.landingPosition, 0.125f, ChaosCollisions.layerPit);
		parent.facingDirection = (parent.endRight ? FacingDirection.Right : FacingDirection.Left);
		landed = false;
	}
	public override void Update()
	{
		if (landed && ChaosStopwatch.Check(delayStopwatchID))
		{
			fsm.ChangeState("Idle");
		}
	}
	public override void OnExit()
	{
		parent.attack.collider.enabled = false;
	}
	public void HandleLandingEvent()
	{
		landed = true;
		parent.rigidbody2D.velocity = Vector3.zero;
		parent.rigidbody2D.isKinematic = true;
		parent.ToggleColliders(status: true);
		parent.ToggleLayers(status: true);
		if (!landingIsSafe)
		{
			parent.destroyDelay = 0f;
			return;
		}
		CameraController.ShakeCamera(1f, ignoreShakeCount: true);
		delayStopwatchID = ChaosStopwatch.Begin(parent.jumpDelay);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 40;
		float scale = 0.25f;
		Vector3? emitPosition = parent.transform.position + Vector3.down * 0.25f;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		if (parent.empoweredJump)
		{
			EarthBurst.CreateBurst(parent.transform.position, parent.skillCategory, parent.attack.atkInfo.skillID, 3).skipParticleEmit = true;
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(parent.debrisType, 10, parent.transform.position, RockDebrisEmitter.FloorExplosionOverride);
			PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(parent.debrisType, 5, parent.transform.position, RockDebrisEmitter.FloorExplosionOverride);
			if (parent.gameObject != null)
			{
				UnityEngine.Object.Destroy(parent.gameObject);
			}
		}
	}
}
