	PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(debrisType, 3, transform.position + Vector3.up * 1.125f, RockDebrisEmitter.SmallCircleSlowExplosionOverride);
	PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(debrisType, 3, transform.position + Vector3.up * 2.5f, RockDebrisEmitter.SmallCircleSlowExplosionOverride);
	PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(debrisType, 3, transform.position + Vector3.up * 1.125f);
