			{
				atkStarted = true;
				atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, atkInterval, atkCount);
				StopAudio();
			}
			switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
			{
			case StopwatchState.Running:
				curAnimTime = parent.anim.GetAnimTime();
				if (curAnimTime < 0.5f || curAnimTime >= 1f)
				{
					parent.anim.Play("Attack", -1, 0f);
