			case StopwatchState.Ready:
			{
				currentPosition = parent.transform.position;
				parent.anim.Play("Attack", -1, 0.5f);
				CreateThrownFireball(currentPosition, Random.insideUnitCircle.normalized * Random.Range(1f, parent.attackRadius));
				DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
				int particleCount = 20;
				float scale = 0.1f;
				float startSpeed = 4f;
				Vector3? emitPosition = currentPosition;
				poolItem.EmitCircle(particleCount, scale, startSpeed, -1f, emitPosition);
				break;
			}
			case StopwatchState.Done:
				base.ExecuteAttack();
				break;
			}
		}
