using UnityEngine;

public class EnemyTargetLine : TargetLine
{
	public int skillTimerID = -1;

	public float flashThreshold = 0.85f;

	public float solidRedThreshold = 0.9f;

	public float flashInterval = 0.018f;

	public float maxOpacity = 0.6f;

	private ChaosQuickStopwatch flashTimer;

	public Color curColor;

	public Color lineColor0;

	public Color lineColor1;

	private bool setColor0 = true;

	internal new static GameObject _prefab;

	public new static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/UI/EnemyTargetLine.prefab");
			}
			return _prefab;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		lineColor0 = new Color(0.8f, 0f, 0f, 0f);
		lineColor1 = new Color(1f, 1f, 1f, 0.75f);
		curColor = lineColor0;
	}

	private void Start()
	{
		line.SetColors(curColor, curColor);
	}

	private void Update()
	{
		if (skillTimerID == -1)
		{
			return;
		}
		float timePercentage = ChaosStopwatch.GetTimePercentage(skillTimerID);
		if (timePercentage >= 0.9f)
		{
			curColor = lineColor0;
			curColor.a = 1f;
		}
		else if (timePercentage >= 0.8f)
		{
			if (flashTimer == null)
			{
				flashTimer = new ChaosQuickStopwatch(flashInterval);
				flashTimer.IsRunning = true;
				curColor.a = 1f;
			}
			else if (!flashTimer.IsRunning)
			{
				if (setColor0)
				{
					curColor = lineColor0;
					curColor.a = 1f;
					setColor0 = false;
				}
				else
				{
					setColor0 = true;
					curColor = lineColor1;
				}
				flashTimer = new ChaosQuickStopwatch(flashInterval);
				flashTimer.IsRunning = true;
			}
		}
		else
		{
			curColor.a = maxOpacity * timePercentage;
		}
		line.SetColors(curColor, curColor);
	}
}
